package com.johnny.hotel.group;import com.johnny.hotel.entity.Booking;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;
@Service@RequiredArgsConstructor public class GroupSlotService{private final GroupMapper db;private final RoomTypeCapacityGuard capacity;public void returnAfterCancellation(Booking booking){if(booking.getGroupBlockId()==null)return;var entry=db.entryByBooking(booking.getId());if(entry==null||entry.getStatus()!=2)return;var block=db.lockBlock(booking.getGroupBlockId());if(block==null)return;capacity.lockAndRead(block.getRoomTypeId(),block.getStartDate(),block.getEndDate());var group=db.lockGroup(block.getGroupId());if(group!=null&&group.getStatus()==2&&(block.getCutOffDate()==null||java.time.LocalDate.now().isBefore(block.getCutOffDate()))){if(db.returnSlot(block.getId())!=1)throw new IllegalStateException("Group pickup quantity is inconsistent");}else{if(db.returnSlot(block.getId())!=1||db.release(block.getId(),1)!=1)throw new IllegalStateException("Group release quantity is inconsistent");}if(db.releaseEntry(entry.getId())!=1)throw new IllegalStateException("Group rooming entry changed concurrently");}}
